static void FlecsGeneratedBody_QueryBuilder_optional_tag_is_set_894f0cc2() {
    flecs::world ecs;

    struct TagA { };
    struct TagB { };

    auto q = ecs.query_builder()
        .with<TagA>()
        .with<TagB>().oper(flecs::Optional)
        .cache_kind(cache_kind)
        .build();

    auto e_1 = ecs.entity().add<TagA>().add<TagB>();
    auto e_2 = ecs.entity().add<TagA>();

    int count = 0;

    q.run([&](flecs::iter& it) {
        while (it.next()) {
            test_int(it.count(), 1);

            count += it.count();
            
            if (it.entity(0) == e_1) {
                test_bool(it.is_set(0), true);
                test_bool(it.is_set(1), true);
            } else {
                test_assert(it.entity(0) == e_2);
                test_bool(it.is_set(0), true);
                test_bool(it.is_set(1), false);
            }
        }
    });

    test_int(count, 2);
}

